    const aChunks = a.match(/(\d+)|([^0-9])/g);
    const bChunks = b.match(/(\d+)|([^0-9])/g);
    if (!aChunks || !bChunks) return a.localeCompare(b);
    for (let i = 0; i < aChunks.length && i < bChunks.length; i++) {
      const ai = aChunks[i];
      const bi = bChunks[i];
      const da = /^\d+$/.test(ai);
      const db = /^\d+$/.test(bi);
      if (da && db) {
        if (ai !== bi) return +ai - +bi;
      } else if (da) {
        return -1;
      } else if (db) {
        return 1;
      } else {
        if (ai !== bi) return ai < bi ? -1 : 1;
      }
    }
    return a.length - b.length;
  });
}
